<header class="admin-top"><button class="mobile-menu" aria-label="Deschide meniul" onclick="document.body.classList.toggle('menu-open')"><x-aura-admin::icon name="menu" /></button><a class="brand" href="{{ route('aura.admin.dashboard') }}"><span class="crown"><x-aura-admin::icon name="crown" /></span>Aura <em>Admin</em><span class="premium">Admin</span></a><div class="top-search"><x-aura-admin::icon name="search" /><input aria-label="Căutare globală" placeholder="Caută utilizator, oportunitate, misiune…" oninput="globalSearch(this.value)"><div id="global-results"></div></div><div class="top-actions"><button class="notice-dot" aria-label="Notificări administrator" onclick="alerts()"><x-aura-admin::icon name="bell" /></button><button class="help-button" aria-label="Ajutor" onclick="@if($projectAdmin ?? false)info('Administrare proiecte','Gestionează oportunitățile, alocările și verificările.')@else info('Despre demonstrație','Toate datele și acțiunile sunt demonstrative. Nu există plăți, emailuri, suspendări sau acces API real.')@endif"><x-aura-admin::icon name="help" /></button><button class="profile-toggle" aria-label="Meniul administratorului" aria-expanded="false" onclick="@if($projectAdmin ?? false)toggleProjectMenu()@else profileOpen=!profileOpen;render()@endif"><span class="admin-avatar"><x-aura-admin::icon name="crown" /></span><span class="profile-text"><b>{{ ($projectAdmin ?? false) ? auth()->user()->name : 'Liviu' }}</b>Super Administrator</span>⌄</button></div></header>
